create table if not exists public.store_settings (id text primary key, brand_name text not null, legal_name text, tagline text, currency text not null default 'PKR', country text, updated_at timestamptz not null default now());
create table if not exists public.catalog_categories (id bigserial primary key, slug text not null unique, name text not null, description text, sort_order integer not null default 0, active boolean not null default true, created_at timestamptz not null default now());
alter table public.store_settings enable row level security;
alter table public.catalog_categories enable row level security;
drop policy if exists "Public can read store settings" on public.store_settings;
create policy "Public can read store settings" on public.store_settings for select to anon, authenticated using (true);
drop policy if exists "Public can read active catalog categories" on public.catalog_categories;
create policy "Public can read active catalog categories" on public.catalog_categories for select to anon, authenticated using (active = true);
insert into public.store_settings (id,brand_name,legal_name,tagline,currency,country) values ('default','Bhatti Electric Store','Bhatti / Industrial Electrical Supply','Reliable electrical supply / local expertise','PKR','Pakistan') on conflict (id) do update set brand_name=excluded.brand_name,legal_name=excluded.legal_name,tagline=excluded.tagline,currency=excluded.currency,country=excluded.country,updated_at=now();
insert into public.catalog_categories (slug,name,description,sort_order) values ('lighting','Lighting','LED, flood, batten and commercial lighting',10),('wiring','Wiring','General wiring and installation conductors',20),('wires-cables','Wires & Cables','Copper cable and flexible conductors',25),('conduit-pvc','Conduit & PVC','Conduit, trunking, boxes and PVC installation products',30),('switches-sockets','Switches & Sockets','Modular switches, sockets and industrial outlets',40),('circuit-protection','Circuit Protection','MCBs, RCCBs, breakers and protective devices',50),('fans','Fans','Ceiling, exhaust and ventilation fans',60),('protection','Protection','Distribution boards and electrical protection hardware',70) on conflict (slug) do update set name=excluded.name,description=excluded.description,sort_order=excluded.sort_order,active=true;